  name = "research-jobs"
  state = "ENABLED"
  priority = 10
  compute_environment_order {
    compute_environment = var.environment_arn
    order = 0
  }
  compute_environment_order {
    compute_environment = "arn:aws:batch:us-east-1:123456789012:compute-environment/backup"
    order = 1
  }
}
